    @Test void cancellationQuoteUsesOriginalUnitsAndShipping() throws Exception {
        var f=paymentFixture("c-quote-original",false);var shipment=paidShipment(f);var unit=shipment.units().getFirst();long original=jdbc.queryForObject("SELECT net FROM marketplace.order_unit WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.orderItemId(),"o",unit.ordinal()),Long.class);var body=Map.of("units",List.of(Map.of("itemId",unit.orderItemId(),"ordinal",unit.ordinal())),"reason","발송 전 취소","expectedRevision",0);var response=accountRequest(f.browser(),"POST","/api/orders/"+f.order().orderNumber()+"/cancellations/quote",body,csrfToken(f.browser()));assertEquals(200,response.statusCode(),"actual cancellation quote must use persisted original units");var quote=authMapper.readTree(response.body());assertEquals(Long.toString(original),quote.get("itemAmount").asText());assertEquals("P09-C-CANCEL-1",quote.get("policyVersion").asText());assertEquals(1,quote.get("units").size());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_unit_hold WHERE order_id=:id",Map.of("id",f.order().id()),Integer.class),"quote does not acquire dispatch hold");assertEquals(400,accountRequest(f.browser(),"POST","/api/orders/"+f.order().orderNumber()+"/cancellations/quote","invalid-string-instead-of-object",csrfToken(f.browser())).statusCode());
    }

    @Test void cancellationReservesBeforeRefundAndRestoresOriginalUnitOnce() throws Exception {
        var f=paymentFixture("a-c-item",false);var shipment=paidShipment(f);var unit=shipment.units().getFirst();UUID sku=jdbc.queryForObject("SELECT sku_id FROM marketplace.order_item WHERE id=:id",Map.of("id",unit.orderItemId()),UUID.class);long before=jdbc.queryForObject("SELECT on_hand FROM marketplace.inventory_balance WHERE sku_id=:id",Map.of("id",sku),Long.class);
        var selected=List.of(Map.of("itemId",unit.orderItemId(),"ordinal",unit.ordinal()));var quoteResponse=accountRequest(f.browser(),"POST","/api/orders/"+f.order().orderNumber()+"/cancellations/quote",Map.of("units",selected,"reason","원단위 취소","expectedRevision",0),csrfToken(f.browser()));assertEquals(200,quoteResponse.statusCode());var quote=authMapper.readTree(quoteResponse.body());
        var command=Map.of("key","original-unit-cancel","units",selected,"reason","원단위 취소","expectedRevision",0,"quoteFingerprint",quote.get("fingerprint").asText());String path="/api/orders/"+f.order().orderNumber()+"/cancellations";var accepted=accountRequest(f.browser(),"POST",path,command,csrfToken(f.browser()));assertEquals(202,accepted.statusCode(),"T1 cancellation must atomically reserve the real original unit");var receipt=authMapper.readTree(accepted.body());UUID claim=UUID.fromString(receipt.get("claimId").asText()),attempt=UUID.fromString(receipt.get("refundAttemptId").asText());
        assertEquals("HELD",jdbc.queryForObject("SELECT state FROM marketplace.order_unit_lifecycle WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.orderItemId(),"o",unit.ordinal()),String.class));assertEquals("RESERVED",jdbc.queryForObject("SELECT state FROM marketplace.payment_refund_attempt WHERE id=:id",Map.of("id",attempt),String.class));assertEquals(before,jdbc.queryForObject("SELECT on_hand FROM marketplace.inventory_balance WHERE sku_id=:id",Map.of("id",sku),Long.class));
        runCancellationJob("REFUND_SUBMIT.v1",attempt);assertEquals("SUCCEEDED",jdbc.queryForObject("SELECT state FROM marketplace.payment_refund_attempt WHERE id=:id",Map.of("id",attempt),String.class));assertEquals(before,jdbc.queryForObject("SELECT on_hand FROM marketplace.inventory_balance WHERE sku_id=:id",Map.of("id",sku),Long.class),"T3 money success precedes T4 stock effects");runCancellationJob("REFUND_RESULT_RECORDED.v1",attempt);
        assertEquals("REFUNDED",jdbc.queryForObject("SELECT state FROM marketplace.order_unit_lifecycle WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.orderItemId(),"o",unit.ordinal()),String.class));assertEquals(before+1,jdbc.queryForObject("SELECT on_hand FROM marketplace.inventory_balance WHERE sku_id=:id",Map.of("id",sku),Long.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.inventory_restitution_unit WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.orderItemId(),"o",unit.ordinal()),Integer.class));assertEquals("COMPLETED",jdbc.queryForObject("SELECT state FROM marketplace.claim WHERE id=:id",Map.of("id",claim),String.class));assertEquals("PAID",orders().find(f.order().orderNumber()).state());
        assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.coupon_restoration WHERE seller_order_ref=:id",Map.of("id",ownSeller(f)),Integer.class));assertEquals(receipt,authMapper.readTree(accountRequest(f.browser(),"POST",path,command,csrfToken(f.browser())).body()));assertEquals(before+1,jdbc.queryForObject("SELECT on_hand FROM marketplace.inventory_balance WHERE sku_id=:id",Map.of("id",sku),Long.class));assertEquals("COMMITTED",jdbc.queryForObject("SELECT status FROM marketplace.inventory_reservation WHERE order_item_id=:id",Map.of("id",unit.orderItemId()),String.class));
    }

    @Test void fullCancellationRefundsOriginalShippingAndClosesOnlyAfterEverySeller() throws Exception {
        var f=paymentFixture("a-c-full",false);paidShipment(f);long succeeded=0;
        for(var seller:f.order().sellers()) {
            var detail=context.getBean(com.example.marketplace.order.api.OrderQueries.class).detail(f.order().orderNumber(),shipmentAuthority(f));var original=detail.stores().stream().filter(s->s.sellerOrderId().equals(seller.id())).findFirst().orElseThrow();var units=original.items().stream().flatMap(i->i.units().stream().map(u->Map.of("itemId",i.id(),"ordinal",u.ordinal()))).toList();var receipt=acceptCancellation(f,units,"whole-"+seller.id());UUID claim=UUID.fromString(receipt.get("claimId").asText()),item=UUID.fromString(receipt.get("refundAttemptId").asText());runCancellationJob("REFUND_SUBMIT.v1",item);runCancellationJob("REFUND_RESULT_RECORDED.v1",item);
            assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.payment_refund_attempt WHERE claim_id=:id AND purpose='SHIPPING'",Map.of("id",claim),Integer.class),"only the last successful original item creates one separate shipping leg");UUID shipping=jdbc.queryForObject("SELECT id FROM marketplace.payment_refund_attempt WHERE claim_id=:id AND purpose='SHIPPING'",Map.of("id",claim),UUID.class);assertEquals(Long.parseLong(original.shippingBase())-Long.parseLong(original.shippingDiscount()),jdbc.queryForObject("SELECT amount FROM marketplace.payment_refund_attempt WHERE id=:id",Map.of("id",shipping),Long.class));assertEquals("SETTLEMENT_PENDING",jdbc.queryForObject("SELECT state FROM marketplace.claim WHERE id=:id",Map.of("id",claim),String.class));assertEquals("PAID",orders().find(f.order().orderNumber()).state());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.coupon_restoration WHERE seller_order_ref=:id",Map.of("id",seller.id()),Integer.class));
            runCancellationJob("REFUND_SUBMIT.v1",shipping);runCancellationJob("REFUND_RESULT_RECORDED.v1",shipping);assertEquals("COMPLETED",jdbc.queryForObject("SELECT state FROM marketplace.claim WHERE id=:id",Map.of("id",claim),String.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.coupon_restoration WHERE seller_order_ref=:id AND restored",Map.of("id",seller.id()),Integer.class));succeeded=Math.addExact(succeeded,Long.parseLong(original.total()));assertEquals(succeeded,jdbc.queryForObject("SELECT succeeded FROM marketplace.payment_refund_budget WHERE order_id=:id",Map.of("id",f.order().id()),Long.class));
        }
        assertEquals(f.order().quote().total(),succeeded);assertEquals("CANCELED",orders().find(f.order().orderNumber()).state());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_event WHERE order_id=:id AND action='CANCELED'",Map.of("id",f.order().id()),Integer.class));var before=aftercareState();payments().apply(f.order().orderNumber(),com.example.marketplace.payment.api.PaymentProvider.Result.SUCCEEDED);assertEquals(before,aftercareState(),"customer cancellation evidence must prevent a second late-success compensation");assertEquals("NONE",paymentAttempt(f).get("compensation"));
    }

