    @Test void productReturnPolicyChangeAndOrderCreationKeepSnapshotOnBothLockOrders() throws Exception {
        for(boolean saveFirst:List.of(true,false)) {
            var source=orderDraft("c-policy-race-"+saveFirst);UUID seller=source.memberId(),buyer=activeMember("c-policy-distinct-buyer-"+saveFirst+"@example.com");assertFalse(buyer.equals(seller));var line=source.quote().stores().getFirst().lines().getFirst();var lines=List.of(quoteLine(line.skuId(),1));var original=quotes().calculate(buyer,lines,List.of());assertEquals("3000",original.stores().getFirst().lines().getFirst().returnPolicy().amount());var draft=new com.example.marketplace.order.api.Orders.Draft(source.purchaseSessionId(),source.requestKey(),source.requestHash(),buyer,null,null,source.mode(),original,source.contact(),source.createdAt(),source.expiresAt());var products=context.getBean(com.example.marketplace.catalog.api.Products.class);var product=products.own(seller,line.productId());var change=new com.example.marketplace.catalog.api.Products.Input(product.categoryId(),product.slug(),product.title(),product.description(),product.state(),product.version(),"5000");var input=creationInput(draft);
            try(var pool=Executors.newFixedThreadPool(2)) {
                if(saveFirst){
                    var before=orderParticipantState();var pending=new java.util.concurrent.atomic.AtomicReference<java.util.concurrent.Future<Integer>>();
                    new TransactionTemplate(transactionManager).executeWithoutResult(t->{products.save(seller,product.id(),change);assertEquals("5000",products.own(seller,product.id()).returnPolicy().amount());pending.set(pool.submit(()->assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->creation().create(draft.purchaseSessionId().toString(),buyer,null,input)).status()));awaitCouponLock("identity_user");recordPolicyOrderWait(saveFirst,buyer,seller);});
                    assertEquals(409,pending.get().get(10,TimeUnit.SECONDS));assertEquals(before,orderParticipantState());var changed=quotes().calculate(buyer,lines,List.of());assertEquals("5000",changed.stores().getFirst().lines().getFirst().returnPolicy().amount());assertFalse(original.fingerprint().equals(changed.fingerprint()));
                }else{
                    var reached=new CountDownLatch(1);var release=new CountDownLatch(1);var api=creationWith(context.getBean(com.example.marketplace.guest.api.GuestOrders.class),stage->{if(stage.equals("ORDER")){reached.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));}});var saved=pool.submit(()->api.create(draft.purchaseSessionId().toString(),buyer,null,input));
                    try{assertTrue(reached.await(5,TimeUnit.SECONDS));var changed=pool.submit(()->products.save(seller,product.id(),change));awaitCouponLock("identity_user");recordPolicyOrderWait(saveFirst,buyer,seller);release.countDown();var order=saved.get(10,TimeUnit.SECONDS);assertEquals(buyer,order.memberId());assertEquals("3000",order.quote().stores().getFirst().lines().getFirst().returnPolicy().amount());assertEquals(original.fingerprint(),order.quote().fingerprint());assertEquals("5000",changed.get(10,TimeUnit.SECONDS).returnPolicy().amount());assertEquals(order,orders().find(order.orderNumber()));}finally{release.countDown();}
                }
            }
            assertEquals("5000",products.own(seller,product.id()).returnPolicy().amount());
        }
    }

