            UUID original=jdbc.queryForObject("SELECT id FROM marketplace.job WHERE type='REFUND_RESULT_RECORDED.v1' AND cause_key=:cause ORDER BY scheduled_at,id LIMIT 1",Map.of("cause",attempt.toString()),UUID.class);var command=context.getBean(com.example.marketplace.platform.api.Jobs.class).find(original).orElseThrow().command();
            var stages=purpose.equals("ITEM")?List.of("RESULT_RECEIPT","UNITS","INVENTORY","SHIPPING_RESERVE","EFFECT_HISTORY","EFFECT_OUTBOX","LEASE"):List.of("RESULT_RECEIPT","SHIPPING_EFFECT","COUPON","CLOSURE","EFFECT_HISTORY","EFFECT_OUTBOX","LEASE");
            for(String point:stages) {
                var clock=new JobClock();clock.now=Instant.now();UUID id=context.getBean(com.example.marketplace.platform.api.Jobs.class).enqueue(new com.example.marketplace.platform.api.Jobs.Command(command.type(),"success-t4-rollback:"+attempt+":"+point,command.causeKey(),command.payload(),clock.now));var jobs=new com.example.marketplace.platform.infrastructure.JdbcJobs(new OneJobJdbc(context.getBean(DataSource.class),id),transactionManager,clock);var before=cancellationEffectParticipants();var reached=new AtomicBoolean();var api=claimsWith(jobs,stage->{if(stage.equals(point)){reached.set(true);throw new java.io.IOException("SUCCESS_T4_"+point);}if(point.equals("LEASE")&&stage.equals("EFFECT_OUTBOX")){var leased=jobs.find(id).orElseThrow();assertEquals("RUNNING",leased.status());assertTrue(leased.leaseUntil().isAfter(clock.now));clock.now=leased.leaseUntil().plusNanos(1000);reached.set(true);}});var handler=new com.example.marketplace.platform.api.JobHandler(){public String type(){return "REFUND_RESULT_RECORDED.v1";}public Result handle(com.example.marketplace.platform.api.Jobs.Job job){return api.result(job);}};
                try(var worker=new com.example.marketplace.platform.infrastructure.WorkerEngine(jobs,List.of(handler))){assertTrue(worker.runOnce());}assertTrue(reached.get(),purpose+":"+point);assertFalse(jobs.find(id).orElseThrow().status().equals("SUCCEEDED"));assertEquals(before,cancellationEffectParticipants(),"all business writes roll back after actual provider success: "+purpose+":"+point);assertEquals(1,jdbc.queryForObject("SELECT submit_calls FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));
            }
