    @Test void refundReviewAckCrashAndOlderUnknownCannotRewindSuccess() throws Exception {
        for(String state:List.of("FAILED","UNKNOWN")) {
            var f=paymentFixture("a-c-ack-"+state.toLowerCase(java.util.Locale.ROOT),false);var v=paidShipment(f);var u=v.units().getFirst();var accepted=acceptCancellation(f,List.of(Map.of("itemId",u.orderItemId(),"ordinal",u.ordinal())),"ack");UUID claim=UUID.fromString(accepted.get("claimId").asText()),attempt=UUID.fromString(accepted.get("refundAttemptId").asText());jdbc.update("INSERT INTO marketplace.payment_refund_mock_setting VALUES(:claim,'ITEM',:state)",Map.of("claim",claim,"state",state));runCancellationJob("REFUND_SUBMIT.v1",attempt);var jobs=context.getBean(com.example.marketplace.platform.api.Jobs.class);UUID id=jdbc.queryForObject("SELECT id FROM marketplace.job WHERE type='REFUND_RESULT_RECORDED.v1' AND cause_key=:cause",Map.of("cause",attempt.toString()),UUID.class);String oldPayload=jobs.find(id).orElseThrow().command().payload();Instant now=jobs.find(id).orElseThrow().nextRunAt().plusSeconds(1);var folder=java.nio.file.Files.createDirectory(java.nio.file.Path.of(System.getenv("A3_EVIDENCE")).resolve("refund-review-ack-"+UUID.randomUUID()));Process first=refundProcess(folder,"first",now,id,"ACK"),second=null;
            try {
                awaitJobCondition(()->java.nio.file.Files.exists(folder.resolve("first-effect"))||!first.isAlive(),"result child did not commit before ACK");assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect")),"inspect ACK child log");var committed=jdbc.queryForMap("SELECT * FROM marketplace.claim WHERE id=:id",Map.of("id",claim));assertEquals("REVIEW_REQUIRED",committed.get("state"));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_refund_result_receipt WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_event WHERE claim_id=:id AND action=:action",Map.of("id",claim,"action","REFUND_"+state),Integer.class));first.destroyForcibly();assertTrue(ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS));second=refundProcess(folder,"restart",now.plusSeconds(31),id,"NORMAL");assertTrue(ContractTiming.awaitProcess(second,40,TimeUnit.SECONDS));assertEquals(0,second.exitValue());assertEquals(committed,jdbc.queryForMap("SELECT * FROM marketplace.claim WHERE id=:id",Map.of("id",claim)));assertEquals(2,jobs.find(id).orElseThrow().attempts());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.outbox_event e JOIN marketplace.job j ON j.id=e.job_id WHERE j.dedupe_key LIKE :prefix",Map.of("prefix","claim-review-result:"+attempt+":%"),Integer.class));
                if(state.equals("UNKNOWN")) {
                    jdbc.update("UPDATE marketplace.payment_refund_mock SET state='SUCCEEDED',reference=:ref,effects=1 WHERE attempt_id=:id",Map.of("ref","DEMO-REFUND-"+attempt,"id",attempt));new TransactionTemplate(transactionManager).executeWithoutResult(t->context.getBean(com.example.marketplace.payment.api.Refunds.class).requestQuery(attempt,UUID.randomUUID(),"ACK 재생 이후 보존된 UNKNOWN 명시조회"));runCancellationJob("REFUND_SUBMIT.v1",attempt);runCancellationJob("REFUND_RESULT_RECORDED.v1",attempt);assertEquals("COMPLETED",jdbc.queryForObject("SELECT state FROM marketplace.claim WHERE id=:id",Map.of("id",claim),String.class));var completed=jdbc.queryForMap("SELECT * FROM marketplace.claim WHERE id=:id",Map.of("id",claim));jobs.enqueue(new com.example.marketplace.platform.api.Jobs.Command("REFUND_RESULT_RECORDED.v1","old-unknown-after-success:"+attempt,attempt.toString(),oldPayload,Instant.now()));runCancellationJob("REFUND_RESULT_RECORDED.v1",attempt);assertEquals(completed,jdbc.queryForMap("SELECT * FROM marketplace.claim WHERE id=:id",Map.of("id",claim)));assertEquals(1,jdbc.queryForObject("SELECT submit_calls FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",attempt),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.inventory_restitution_unit WHERE item_id=:i AND ordinal=:o",Map.of("i",u.orderItemId(),"o",u.ordinal()),Integer.class));
                }
            }finally { if(first.isAlive()) { first.destroyForcibly();ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS); }if(second!=null&&second.isAlive()) { second.destroyForcibly();ContractTiming.awaitProcess(second,10,TimeUnit.SECONDS); } }
        }
    }

