        var f=returnFeeFixture("result-"+behavior.toLowerCase(java.util.Locale.ROOT),false);var shipment=paidShipment(f);completeShipment(f,shipment,Instant.now());var unit=shipment.units().getFirst();var accepted=acceptReturnFee(f,List.of(new com.example.marketplace.claim.api.ReturnFees.Target(unit.orderItemId(),unit.ordinal(),com.example.marketplace.claim.api.ReturnFees.Responsibility.BUYER)),"result-once");jdbc.update("INSERT INTO marketplace.payment_refund_mock_setting(claim_id,purpose,behavior) VALUES(:id,'ITEM',:behavior)",Map.of("id",accepted.accepted().intentId(),"behavior",behavior));String expected=behavior.equals("SUCCESS")?"SUCCEEDED":behavior;
