    private List<com.example.marketplace.platform.api.JobHandler> fRefundHandlers(){var result=new java.util.ArrayList<com.example.marketplace.platform.api.JobHandler>();for(var delegate:context.getBeansOfType(com.example.marketplace.platform.api.JobHandler.class).values()){if(!delegate.type().equals("REFUND_QUERY_DUE.v1")){result.add(delegate);continue;}result.add(new com.example.marketplace.platform.api.JobHandler(){public String type(){return delegate.type();}public Result handle(com.example.marketplace.platform.api.Jobs.Job job) throws Exception{try{return delegate.handle(job);}catch(Exception failure){var text=new java.io.StringWriter();failure.printStackTrace(new java.io.PrintWriter(text));java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"f-auto-"+job.id()+"-failure.txt"),text.toString());throw failure;}}});}return List.copyOf(result);}
    private void runFRefundAuto(UUID id,JobClock clock){var jobs=new com.example.marketplace.platform.infrastructure.JdbcJobs(new OneJobJdbc(context.getBean(DataSource.class),id),transactionManager,clock);try(var worker=new com.example.marketplace.platform.infrastructure.WorkerEngine(jobs,fRefundHandlers())){assertTrue(worker.runOnce());}assertEquals("SUCCEEDED",jobs.find(id).orElseThrow().status());}

