        var foreign=fProviderRefund("sql-foreign");runCancellationJob("REFUND_SUBMIT.v1",foreign.attempt());var foreignRequest=jdbc.queryForMap("SELECT * FROM marketplace.payment_refund_provider_request WHERE attempt_id=:id",Map.of("id",foreign.attempt()));var foreignCall=jdbc.queryForObject("SELECT id FROM marketplace.payment_refund_provider_call WHERE attempt_id=:id",Map.of("id",foreign.attempt()),UUID.class);
